const b = $json.body ?? $json;
const campos = ['nome', 'canal', 'mensagem'];
const ausentes = campos.filter((c) => typeof b[c] !== 'string' || !b[c].trim());
if (ausentes.length) throw new Error(`Campos obrigatórios ausentes ou inválidos: ${ausentes.join(', ')}`);
return [{ json: { nome: b.nome.trim(), canal: b.canal.trim(), mensagem: b.mensagem.trim(), recebido_em: new Date().toISOString() } }];

const entrada = $('Normalizar entrada').item.json;
const permitidas = ['dúvida', 'reclamação', 'pedido', 'elogio', 'outro'];
const prioridades = ['alta', 'média', 'baixa'];
let bruto = $json.text ?? $json.output ?? $json.response ?? '';
let parsed;
let valido = true;
try {
  if (typeof bruto === 'string') {
    bruto = bruto.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
    parsed = JSON.parse(bruto);
  } else { parsed = bruto; }
  valido = parsed && permitidas.includes(parsed.categoria) && prioridades.includes(parsed.prioridade) && typeof parsed.resumo === 'string' && parsed.resumo.trim().length > 0;
} catch { valido = false; }
const resultado = valido ? parsed : { categoria: 'outro', prioridade: 'baixa', resumo: 'Saída da classificação requer revisão manual.' };
return [{ json: { data: entrada.recebido_em, categoria: resultado.categoria, prioridade: resultado.prioridade, resumo: resultado.resumo.trim(), status: valido ? 'classificado' : 'revisar manualmente', nome: entrada.nome, canal: entrada.canal } }];

